import {CASES} from './cases.js';
export const caseById=Object.fromEntries(CASES.map(c=>[c.id,c]));
export function freshCase(){return {index:0,answers:[],draft:null,hints:[],note:'',status:'',attempts:0,best:0};}
export function numericValue(value){if(typeof value!=='string'&&typeof value!=='number')return null;const s=String(value).trim().replace(',','.');if(!/^-?\d+(\.\d+)?$/.test(s))return null;const n=Number(s);return Number.isFinite(n)?n:null;}
export function caseReady(step,value){if(!step)return false;if(step.type==='reason')return typeof value==='string'&&value.trim().length>=12&&value.length<=6000;if(step.type==='number')return numericValue(value)!==null;const valid=i=>Number.isInteger(i)&&i>=0&&i<step.options.length;if(step.type==='multi')return Array.isArray(value)&&value.length>0&&new Set(value).size===value.length&&value.every(valid);return valid(value);}
export function caseCorrect(step,value){if(!caseReady(step,value))return false;if(step.type==='reason')return null;if(step.type==='number')return Math.abs(numericValue(value)-step.answer)<0.005;if(step.type==='multi')return value.length===step.answer.length&&[...value].sort((a,b)=>a-b).every((v,i)=>v===step.answer[i]);return value===step.answer;}
export function caseScore(record,c){return Math.round(record.answers.filter(a=>a.ok===true).length/Math.max(1,c.steps.filter(s=>s.type!=='reason').length)*100);}
export function submitCase(record,c){const s=c.steps[record.index];if(!s||record.answers[record.index]||!caseReady(s,record.draft))return false;record.answers.push({value:structuredClone(record.draft),ok:caseCorrect(s,record.draft),hint:record.hints.includes(record.index)});if(record.answers.length===c.steps.length){record.best=Math.max(record.best,caseScore(record,c));record.attempts++;}return true;}
export function nextCaseStep(record,c){if(record.index>=c.steps.length||!record.answers[record.index])return false;record.index++;record.draft=null;return true;}
export function resetCase(record){return {...freshCase(),note:record.note,best:record.best,attempts:record.attempts};}
export function validateCasework(raw){const result={};if(!raw||typeof raw!=='object')return result;for(const c of CASES){const r=raw[c.id];if(!r||!Array.isArray(r.answers)||r.answers.length>c.steps.length||!Number.isInteger(r.index)||r.index<0||r.index>c.steps.length||!(r.answers.length===r.index||r.answers.length===r.index+1))continue;if(!r.answers.every((a,i)=>a&&caseReady(c.steps[i],a.value)))continue;const v=freshCase();v.index=r.index;v.answers=r.answers.map((a,i)=>({value:structuredClone(a.value),ok:caseCorrect(c.steps[i],a.value),hint:!!a.hint}));v.status=['review','understood'].includes(r.status)?r.status:'';v.note=typeof r.note==='string'?r.note.slice(0,3000):'';v.hints=Array.isArray(r.hints)?[...new Set(r.hints.filter(i=>Number.isInteger(i)&&i>=0&&i<c.steps.length))]:[];v.best=Number.isFinite(r.best)?Math.max(0,Math.min(100,r.best)):0;v.attempts=Number.isInteger(r.attempts)?Math.max(0,Math.min(100000,r.attempts)):0;const s=c.steps[r.index];if(s&&(caseReady(s,r.draft)||s.type==='reason'&&typeof r.draft==='string'&&r.draft.length<=6000))v.draft=structuredClone(r.draft);result[c.id]=v;}return result;}
